import { Cluster, Grid, Section, Stack, Text } from '../layout/layout';
import { Avatar } from '../ui/avatar';
import { Icon } from '../ui/icon';
import type { SectionAnchor } from './types';

export interface TestimonialsProps extends SectionAnchor { items: { quote: string; name: string; role?: string }[] }

export function Testimonials({ id, slug, items }: TestimonialsProps) {
  return (
    <Section id={id} slug={slug} role="testimonials">
      <Grid cols={{ base: 1, md: 2, lg: Math.min(items.length, 3) }}>
        {items.map((it) => (
          <figure key={it.name} style={{ margin: 0 }}>
            <Stack gap="md">
              <Icon name="quote" />
              <blockquote style={{ margin: 0 }}><Text role="body">{it.quote}</Text></blockquote>
              <figcaption>
                <Cluster gap="sm">
                  <Avatar name={it.name} />
                  <Stack gap="none"><Text role="body"><strong>{it.name}</strong></Text>{it.role ? <Text role="caption">{it.role}</Text> : null}</Stack>
                </Cluster>
              </figcaption>
            </Stack>
          </figure>
        ))}
      </Grid>
    </Section>
  );
}

import type { ButtonProps } from '../ui/button';

/** Una acción de sección es un Button con destino: el contrato de bloque pide `actions[]` como datos, no como nodos. */
export type Action = Pick<ButtonProps, 'label' | 'variant'> & { href: string };
export interface NavLink { label: string; href: string }
/** Ancla y slug del contrato de página: el bloque los pasa a su Section, así los sensores y el editor lo encuentran. */
export interface SectionAnchor { id?: string; slug?: string }

/* Primitivas de layout del modo v0: solo posición y espaciado, todo por token. Las escribe el
   equipo, no el agente; el agente solo elige primitiva y valores de la escala. */

.l-section {
  background: var(--l-surface, transparent);
  padding-block: var(--l-pad, var(--space-16));
  padding-inline: var(--space-4);
}
.l-section > .l-container {
  margin-inline: auto;
  max-width: var(--l-width, 72rem);
}
/* Media a sangre: ocupa toda la sección detrás del contenedor, con un velo del fondo de la sección para que el texto
   se lea; el contenedor queda donde está en las demás secciones. */
.l-bare { background: var(--l-surface, var(--background)); }
.l-section--backdrop { position: relative; isolation: isolate; overflow: hidden; }
.l-section--backdrop > .l-container { position: relative; }
.l-backdrop { position: absolute; inset: 0; z-index: -1; }
.l-backdrop::after { content: ''; position: absolute; inset: 0; background: var(--background); opacity: .72; }
.l-backdrop > .l-image, .l-backdrop img { width: 100%; height: 100%; object-fit: cover; border: 0; border-radius: 0; box-shadow: none; }

.l-stack {
  display: flex;
  flex-direction: column;
  gap: var(--l-gap, var(--space-4));
  align-items: var(--l-align, stretch);
}

.l-cluster {
  display: flex;
  flex-wrap: wrap;
  gap: var(--l-gap, var(--space-3));
  justify-content: var(--l-justify, flex-start);
  align-items: var(--l-align, center);
}

.l-grid {
  display: grid;
  gap: var(--l-gap, var(--space-6));
  align-items: var(--l-align, stretch);
  grid-template-columns: repeat(var(--l-cols, 1), minmax(0, 1fr));
}
@media (min-width: 768px) {
  .l-grid { grid-template-columns: repeat(var(--l-cols-md, var(--l-cols, 1)), minmax(0, 1fr)); }
}
@media (min-width: 1024px) {
  .l-grid { grid-template-columns: repeat(var(--l-cols-lg, var(--l-cols-md, var(--l-cols, 1))), minmax(0, 1fr)); }
}

.l-split {
  display: grid;
  gap: var(--l-gap, var(--space-10));
  align-items: var(--l-align, center);
  grid-template-columns: minmax(0, 1fr);
}
@media (min-width: 1024px) {
  .l-split { grid-template-columns: var(--l-ratio, 1fr 1fr); }
}

.l-text { margin: 0; text-align: var(--l-text-align, start); color: var(--foreground); }
.l-text--display { font-family: var(--font-display); font-size: var(--text-5xl); line-height: var(--leading-display); }
.l-text--title { font-family: var(--font-display); font-size: var(--text-3xl); line-height: var(--leading-display); }
.l-text--subtitle { font-family: var(--font-body); font-size: var(--text-lg); line-height: var(--leading-body); color: var(--text-secondary); }
.l-text--body { font-family: var(--font-body); font-size: var(--text-base); line-height: var(--leading-body); }
.l-text--caption { font-family: var(--font-body); font-size: var(--text-sm); line-height: var(--leading-body); color: var(--text-muted); }

.l-image {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--radius-panel);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--shadow-raised);
}

import type { CSSProperties, ReactNode } from 'react';
import './layout.css';

type Space = 'none' | 'xs' | 'sm' | 'md' | 'lg' | 'xl' | '2xl';
type Align = 'start' | 'center' | 'end' | 'stretch';
type Responsive<T> = T | { base: T; md?: T; lg?: T };

const SPACE: Record<Space, string> = {
  none: '0',
  xs: 'var(--space-2)',
  sm: 'var(--space-3)',
  md: 'var(--space-4)',
  lg: 'var(--space-6)',
  xl: 'var(--space-10)',
  '2xl': 'var(--space-16)',
};
const ALIGN: Record<Align, string> = { start: 'flex-start', center: 'center', end: 'flex-end', stretch: 'stretch' };
const WIDTH = { prose: '42rem', narrow: '48rem', content: '72rem', wide: '80rem', full: 'none' } as const;
type Surface = 'base' | 'muted' | 'raised' | 'inverse';
// Lovable, Stitch y v0 coinciden: un contenedor centrado por sección y solo la FAQ más angosta (RE 2026-10-27).
const ROLE_WIDTH: Partial<Record<string, keyof typeof WIDTH>> = { faq: 'narrow' };
const PAD = { none: '0', sm: 'var(--space-8)', md: 'var(--space-12)', lg: 'var(--space-20)' } as const;
const RATIO = { '1:1': '1fr 1fr', '1:2': '1fr 2fr', '2:1': '2fr 1fr' } as const;

// Custom properties en vez de clases por valor: el CSS queda fijo y el token lo resuelve el tema.
// Cada primitiva fija SIEMPRE todas sus variables (con su default): las custom properties se heredan,
// y sin esto el align="center" de un Stack exterior centraba el contenido de las cards anidadas.
const vars = (o: Record<string, string | number>): CSSProperties => o as CSSProperties;

// muted y raised son la banda del contrato (data-wt-surface en theme/tokens.css), no --surface-muted: ese es un gris
// neutro fijo de controles que no sigue la identidad, y con una marca propia la banda quedaba igual a la página
// (live6). El atributo remapea --background en la sección, así que el fondo es siempre var(--background).
// inverse es la zona oscura del cierre: data-theme="dark" resuelve los tokens y el atributo la deja medible.
// id, role y slug son los del contrato de página (anclas y sensores): sin ellos el agente escribía un <section> crudo
// con su propio contenedor, y su margin-inline pisaba el centrado en el mismo nodo (demo cc7b8016, cierre pegado al borde).
// backdrop es la media a sangre (full-bleed): va detrás de toda la sección y el texto sigue en el contenedor. Sin esto
// el agente metía la foto en una tarjeta dentro del contenedor con su propio padding, y el texto del cierre arrancaba
// 64 px más adentro que el resto de la página (gen fac2bce5, section.gutter).
// bare monta un bloque de sección (índice, "Secciones de landing") que trae su propio <section> y contenedor: solo pone
// el ancla, los atributos del contrato y el tema, sin otro contenedor ni padding que se sumen a los del bloque.
export function Section(p: { id?: string; role?: string; slug?: string; width?: keyof typeof WIDTH; surface?: Surface; padding?: keyof typeof PAD; backdrop?: ReactNode; bare?: boolean; children: ReactNode }) {
  const band = p.surface && p.surface !== 'base' ? p.surface : undefined;
  const width = p.width ?? ROLE_WIDTH[p.role ?? ''] ?? 'content';
  if (p.bare) {
    return (
      <div id={p.id} className="l-bare" data-wt-role={p.role} data-wt-slug={p.slug} data-wt-surface={band} data-theme={p.surface === 'inverse' ? 'dark' : undefined}>
        {p.children}
      </div>
    );
  }
  return (
    <section
      id={p.id}
      className={p.backdrop ? 'l-section l-section--backdrop' : 'l-section'}
      data-wt-role={p.role}
      data-wt-slug={p.slug}
      data-wt-surface={band}
      data-theme={p.surface === 'inverse' ? 'dark' : undefined}
      style={vars({ '--l-surface': p.surface ? 'var(--background)' : 'transparent', '--l-pad': PAD[p.padding ?? 'lg'] })}
    >
      {p.backdrop ? <div className="l-backdrop">{p.backdrop}</div> : null}
      <div className="l-container" style={vars({ '--l-width': WIDTH[width] })}>{p.children}</div>
    </section>
  );
}

export function Stack(p: { gap?: Space; align?: Align; children: ReactNode }) {
  return <div className="l-stack" style={vars({ '--l-gap': SPACE[p.gap ?? 'md'], '--l-align': ALIGN[p.align ?? 'stretch'] })}>{p.children}</div>;
}

// Sin modo carrusel: el carrusel móvil de una grilla es de un DS con motion (B9 §2.2); aquí la grilla apila por columnas.
export function Grid(p: { cols: Responsive<number>; gap?: Space; align?: Align; children: ReactNode }) {
  const c = typeof p.cols === 'number' ? { base: p.cols } : p.cols;
  return (
    <div className="l-grid" style={vars({ '--l-cols': c.base, '--l-cols-md': c.md ?? c.base, '--l-cols-lg': c.lg ?? c.md ?? c.base, '--l-gap': SPACE[p.gap ?? 'lg'], '--l-align': ALIGN[p.align ?? 'stretch'] })}>
      {p.children}
    </div>
  );
}

export function Cluster(p: { gap?: Space; justify?: 'start' | 'center' | 'end' | 'between'; align?: Align; children: ReactNode }) {
  const justify = p.justify === 'between' ? 'space-between' : ALIGN[p.justify ?? 'start'];
  return <div className="l-cluster" style={vars({ '--l-gap': SPACE[p.gap ?? 'sm'], '--l-justify': justify, '--l-align': ALIGN[p.align ?? 'center'] })}>{p.children}</div>;
}

export function Split(p: { ratio?: keyof typeof RATIO; gap?: Space; align?: Align; children: ReactNode }) {
  return <div className="l-split" style={vars({ '--l-ratio': RATIO[p.ratio ?? '1:1'], '--l-gap': SPACE[p.gap ?? 'xl'], '--l-align': ALIGN[p.align ?? 'center'] })}>{p.children}</div>;
}

const TAG = { display: 'h1', title: 'h2', subtitle: 'p', body: 'p', caption: 'p' } as const;

export function Text(p: { role: keyof typeof TAG; align?: 'start' | 'center'; children: ReactNode }) {
  const Tag = TAG[p.role];
  return <Tag className={`l-text l-text--${p.role}`} style={vars({ '--l-text-align': p.align ?? 'start' })}>{p.children}</Tag>;
}

// La imagen de producto del paso de imagen: marco por token (radio, borde, sombra) para que se lea como
// captura de producto y el brandpack la repinte; width/height reservan el espacio y evitan el salto.
// data-alt es el prompt del slot (como Stitch): lo lee el paso de imagen, y el alt queda corto para lectores de pantalla.
export function Image(p: { src: string; alt: string; 'data-alt'?: string; width?: number; height?: number }) {
  return <img className="l-image" src={p.src} alt={p.alt} data-alt={p['data-alt']} width={p.width} height={p.height} loading="eager" decoding="async" />;
}

import './ui.css';

export interface AvatarProps {
  name: string;
  src?: string;
}

const initials = (name: string): string => name.split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]!.toUpperCase()).join('');

export function Avatar({ name, src }: AvatarProps) {
  return <span className="ui-avatar">{src ? <img src={src} alt={name} /> : <span aria-label={name} role="img">{initials(name)}</span>}</span>;
}

import './ui.css';

export interface ButtonProps {
  label: string;
  href?: string;
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  type?: 'button' | 'submit';
}

/** Con `href` es un enlace (navega), sin él un botón (acción): la semántica sigue a lo que hace. */
export function Button({ label, href, variant = 'primary', size = 'md', type = 'button' }: ButtonProps) {
  const className = `ui-button ui-button--${variant} ui-button--${size}`;
  return href ? <a className={className} href={href}>{label}</a> : <button className={className} type={type}>{label}</button>;
}

import './ui.css';

// Set propio y chico en SVG inline (B9 §2.3): sin librería de iconos, un clon limpio no instala nada para dibujarlos.
const PATHS = {
  check: 'M5 12l5 5L20 7',
  'arrow-right': 'M5 12h14M13 6l6 6-6 6',
  menu: 'M4 7h16M4 12h16M4 17h16',
  x: 'M6 6l12 12M18 6L6 18',
  plus: 'M12 5v14M5 12h14',
  minus: 'M5 12h14',
  star: 'M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3 6.4 20.2l1.1-6.2L3 9.6l6.2-.9z',
  quote: 'M7 17c-2 0-3-1.5-3-3.5C4 10 6.5 7 10 6l.5 1.5C8.5 8.3 7.5 9.7 7.3 11H10v6zm9 0c-2 0-3-1.5-3-3.5 0-3.5 2.5-6.5 6-7.5l.5 1.5c-2 .8-3 2.2-3.2 3.5H19v6z',
} as const;

export type IconName = keyof typeof PATHS;
export const ICON_NAMES = Object.keys(PATHS) as IconName[];

export interface IconProps {
  name: IconName;
  label?: string;
}

/** Sin `label` es decorativo y se oculta a los lectores de pantalla. */
export function Icon({ name, label }: IconProps) {
  const filled = name === 'star' || name === 'quote';
  return (
    <svg className="ui-icon" viewBox="0 0 24 24" fill={filled ? 'currentColor' : 'none'} stroke={filled ? 'none' : 'currentColor'} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" role={label ? 'img' : undefined} aria-label={label} aria-hidden={label ? undefined : true}>
      <path d={PATHS[name]} />
    </svg>
  );
}

/* Átomos del DS base (B9 §2.3): solo tokens del contrato, así un brand pack los repinta sin tocarlos. */
.ui-button { display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2); border: 1px solid transparent; border-radius: var(--radius-control); font: inherit; font-weight: 500; text-decoration: none; cursor: pointer; transition: background-color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard); }
.ui-button--sm { min-height: var(--control-height-sm); padding-inline: var(--space-3); font-size: var(--text-sm); }
.ui-button--md { min-height: var(--control-height-md); padding-inline: var(--space-4); font-size: var(--text-base); }
.ui-button--lg { min-height: var(--control-height-lg); padding-inline: var(--space-6); font-size: var(--text-lg); }
.ui-button--primary { background: var(--accent); color: var(--accent-foreground); }
.ui-button--primary:hover { background: var(--accent-strong); }
.ui-button--secondary { background: transparent; color: var(--foreground); border-color: var(--border-strong); }
.ui-button--secondary:hover { background: var(--surface-muted); }
.ui-button--ghost { background: transparent; color: var(--foreground); }
.ui-button--ghost:hover { background: var(--accent-subtle); }

.ui-link { color: var(--accent-strong); text-decoration: underline; text-underline-offset: 0.2em; }
.ui-link:hover { color: var(--accent); }

.ui-heading { margin: 0; font-family: var(--font-display); letter-spacing: var(--tracking-display); line-height: var(--leading-display); color: var(--foreground); }
.ui-heading--1 { font-size: var(--text-5xl); }
.ui-heading--2 { font-size: var(--text-3xl); }
.ui-heading--3 { font-size: var(--text-xl); }
.ui-heading--4 { font-size: var(--text-lg); }

.ui-badge { display: inline-flex; align-items: center; padding: var(--space-1) var(--space-3); border-radius: var(--radius-pill); font-size: var(--text-xs); font-weight: 500; background: color-mix(in oklab, var(--ui-tone) 12%, transparent); color: var(--ui-tone); }

.ui-icon { display: inline-block; width: 1.25em; height: 1.25em; flex: none; }

.ui-avatar { display: inline-flex; align-items: center; justify-content: center; width: 2.5rem; height: 2.5rem; border-radius: var(--radius-pill); overflow: hidden; background: var(--surface-muted); color: var(--text-secondary); font-size: var(--text-sm); font-weight: 500; }
.ui-avatar img { width: 100%; height: 100%; object-fit: cover; }

.ui-card { display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface-raised); box-shadow: var(--shadow-resting); height: 100%; }
.ui-card__media { margin: calc(var(--space-6) * -1) calc(var(--space-6) * -1) 0; border-radius: var(--radius-panel) var(--radius-panel) 0 0; overflow: hidden; }
.ui-card__title { margin: 0; font-family: var(--font-display); font-size: var(--text-lg); color: var(--foreground); }
.ui-card__body { margin: 0; color: var(--text-secondary); line-height: var(--leading-body); }
.ui-card__action { margin-top: auto; }

.ui-accordion { display: flex; flex-direction: column; border-top: 1px solid var(--border); }
.ui-accordion__item { border-bottom: 1px solid var(--border); }
.ui-accordion__summary { display: flex; justify-content: space-between; align-items: center; gap: var(--space-4); padding-block: var(--space-4); cursor: pointer; list-style: none; font-weight: 500; color: var(--foreground); }
.ui-accordion__summary::-webkit-details-marker { display: none; }
.ui-accordion__item[open] .ui-accordion__plus, .ui-accordion__item:not([open]) .ui-accordion__minus { display: none; }
.ui-accordion__content { padding-bottom: var(--space-4); color: var(--text-secondary); line-height: var(--leading-body); }

.ui-field { display: flex; flex-direction: column; gap: var(--space-2); font-size: var(--text-sm); color: var(--foreground); }
.ui-field__control { font: inherit; font-size: var(--text-base); padding: var(--space-2) var(--space-3); min-height: var(--control-height-md); border: 1px solid var(--border-strong); border-radius: var(--radius-control); background: var(--background); color: var(--foreground); }
.ui-field__control:focus-visible { border-color: var(--accent); }
